extends Node2D

signal hud_update(loop_time: float, loop_count: int, held: int, required: int, fractions: Array[float])
signal level_completed(loops_used: int, exit_time: float)
signal pause_requested()

const LevelDataScript = preload("res://scripts/level_data.gd")
const PlayerActorScript = preload("res://scripts/player_actor.gd")

const LOOP_DURATION := 30.0
const MAX_TICKS := 900
const PLAYER_TEX_PATH := "res://assets/normalized/player_sprite/player_idle.png"
const PLATFORM_TEX_PATH := "res://assets/normalized/platform_tile/platform_tile.png"
const PLATE_TEX_PATH := "res://assets/normalized/pressure_plate/pressure_plate.png"
const SWITCH_TEX_PATH := "res://assets/normalized/switch_lever/switch_lever.png"
const DOOR_TEX_PATH := "res://assets/normalized/door_prop/door_closed.png"
const LASER_TEX_PATH := "res://assets/normalized/laser_beam/laser_beam.png"
const ENEMY_TEX_PATH := "res://assets/normalized/enemy_distractor/enemy_distractor.png"
const EXIT_TEX_PATH := "res://assets/normalized/exit_crystal/exit_crystal.png"
const GHOST_COLORS = [
	Color(0.35, 0.85, 1.0),
	Color(0.4, 0.55, 1.0),
	Color(0.7, 0.4, 1.0),
	Color(1.0, 0.65, 0.35)
]

var level_id: String = "1-1"
var scenario_id: String = ""
var paused: bool = false
var completed: bool = false
var loop_time: float = LOOP_DURATION
var sim_tick: int = 0
var loop_count: int = 1
var max_loops: int = 4
var required_prop_ids: Array[String] = []
var spawn: Vector2 = Vector2(110.0, 608.0)
var ground_top: float = 640.0
var exit_rect: Rect2 = Rect2()
var exit_sprite: Sprite2D = null
var flash_timer: float = 0.0

var player = null
var current_track = null
var tracks: Array = []
var ghost_sprites: Array[Sprite2D] = []

var pressure_plates: Array[Dictionary] = []
var button_nodes: Array[Dictionary] = []
var switch_nodes: Array[Dictionary] = []
var door_nodes: Array[Dictionary] = []
var lasers: Array[Dictionary] = []
var enemies: Array[Dictionary] = []


class LoopTrack:
	var positions: Array[Vector2] = []
	var flips: Array[bool] = []
	var interact_events: Array[Dictionary] = []
	var tick_count: int = 0

	func record(p_tick: int, p_pos: Vector2, p_flip: bool) -> void:
		while positions.size() <= p_tick:
			positions.append(p_pos)
			flips.append(p_flip)
		positions[p_tick] = p_pos
		flips[p_tick] = p_flip

	func record_interact(p_tick: int, p_switch_id: String) -> void:
		interact_events.append({"tick": p_tick, "switch_id": p_switch_id})

	func finalize(count: int) -> void:
		positions.resize(count)
		flips.resize(count)
		tick_count = count


func _ready() -> void:
	var data: Dictionary = LevelDataScript.get_level_by_id(level_id)
	if data.is_empty():
		data = LevelDataScript.get_level_by_id("1-1")
	spawn = Vector2(data.get("spawn", Vector2(110.0, 608.0)))
	var exit_pos: Vector2 = Vector2(data.get("exit", Vector2(1140.0, 552.0)))
	ground_top = float(data.get("ground_y", 640.0))
	max_loops = int(data.get("max_loops", 4))
	_build_level(
		int(data.get("chapter", 1)),
		int(data.get("index", 1)),
		int(data.get("required_switches", 1)),
		exit_pos
	)
	current_track = LoopTrack.new()
	player = PlayerActorScript.new()
	add_child(player)
	player.global_position = spawn
	player.velocity = Vector2.ZERO
	emit_hud_now()


func _build_level(chapter: int, index: int, required_count: int, exit_pos: Vector2) -> void:
	_add_ground(0.0, 1280.0, ground_top)
	var plate_xs := _plate_x_positions(chapter, index, required_count)
	for i: int in range(plate_xs.size()):
		var id := "plate_%d" % (i + 1)
		_add_pressure_plate(plate_xs[i], id)
		required_prop_ids.append(id)
	if chapter >= 2:
		var door_x := 560.0 + chapter * 15.0 + index * 8.0
		_add_door(door_x, "door_main")
	if chapter >= 3:
		var laser_x := 820.0 + index * 8.0
		_add_laser(laser_x, 180.0, "laser_main")
		_add_enemy(330.0 + index * 14.0, "enemy_main")
	_add_switch(470.0 + index * 15.0, "lever_door")
	_add_exit(exit_pos)


func _plate_x_positions(chapter: int, index: int, count: int) -> Array[float]:
	var arr: Array[float] = []
	var door_x := 560.0 + chapter * 15.0 + index * 8.0
	var laser_x := 820.0 + index * 8.0
	for i: int in range(count):
		var x: float
		if chapter >= 2 and i == 0:
			x = door_x - 45.0
		elif chapter >= 3 and i == 1:
			x = laser_x - 45.0
		else:
			x = 260.0 + i * 220.0 + (index - 1) * 12.0
		arr.append(x)
	return arr


func _fit_scale(tex: Texture2D, display_size: Vector2) -> float:
	var tw := float(tex.get_width())
	var th := float(tex.get_height())
	return minf(display_size.x / tw, display_size.y / th)


func _make_sprite(tex: Texture2D, s: float, pos: Vector2) -> Sprite2D:
	var sp := Sprite2D.new()
	sp.texture = tex
	sp.centered = true
	sp.scale = Vector2(s, s)
	sp.position = pos
	sp.texture_filter = CanvasItem.TEXTURE_FILTER_LINEAR
	return sp


func _add_ground(x1: float, x2: float, y_top: float) -> void:
	var body := StaticBody2D.new()
	body.collision_layer = 1
	body.collision_mask = 0
	var shape := CollisionShape2D.new()
	var rect := RectangleShape2D.new()
	rect.size = Vector2(x2 - x1, 48.0)
	shape.shape = rect
	shape.position = Vector2((x1 + x2) * 0.5, y_top + 24.0)
	body.add_child(shape)
	add_child(body)

	var tex: Texture2D = load(PLATFORM_TEX_PATH)
	var s := _fit_scale(tex, Vector2(128.0, 128.0))
	var step := float(tex.get_width()) * s
	if step <= 0.0:
		step = 128.0
	var x := x1
	while x < x2:
		var sp := _make_sprite(tex, s, Vector2(x + step * 0.5, y_top + step * 0.5))
		add_child(sp)
		x += step


func _add_pressure_plate(x: float, id: String) -> void:
	var tex: Texture2D = load(PLATE_TEX_PATH)
	var s := _fit_scale(tex, Vector2(128.0, 64.0))
	var y := ground_top - (float(tex.get_height()) * s) * 0.5
	var pos := Vector2(x, y)
	var sp := _make_sprite(tex, s, pos)
	add_child(sp)
	pressure_plates.append({
		"id": id,
		"pos": pos,
		"rect": Rect2(x - 60.0, y - 22.0, 120.0, 44.0),
		"sprite": sp,
		"active": false,
		"base_y": y
	})


func _add_switch(x: float, id: String) -> void:
	var tex: Texture2D = load(SWITCH_TEX_PATH)
	var s := _fit_scale(tex, Vector2(128.0, 128.0))
	var y := ground_top - (float(tex.get_height()) * s) * 0.5
	var pos := Vector2(x, y)
	var sp := _make_sprite(tex, s, pos)
	add_child(sp)
	switch_nodes.append({"id": id, "pos": pos, "sprite": sp, "active": false})


func _add_door(x: float, id: String) -> void:
	var tex: Texture2D = load(DOOR_TEX_PATH)
	var s := _fit_scale(tex, Vector2(128.0, 256.0))
	var body := StaticBody2D.new()
	body.collision_layer = 1
	body.collision_mask = 0
	body.position = Vector2(x, ground_top - 55.0)
	var shape := CollisionShape2D.new()
	var rect := RectangleShape2D.new()
	rect.size = Vector2(44.0, 110.0)
	shape.shape = rect
	shape.position = Vector2(0.0, -55.0)
	body.add_child(shape)
	add_child(body)
	var sp := _make_sprite(tex, s, Vector2(0.0, -55.0))
	body.add_child(sp)
	door_nodes.append({
		"id": id,
		"body": body,
		"sprite": sp,
		"hold_rect": Rect2(x - 48.0, ground_top - 130.0, 76.0, 130.0),
		"open": false
	})


func _add_laser(x: float, length: float, id: String) -> void:
	var tex: Texture2D = load(LASER_TEX_PATH)
	var s := _fit_scale(tex, Vector2(256.0, 64.0))
	var visual_step := float(tex.get_width()) * s
	if visual_step <= 0.0:
		visual_step = 64.0
	var beam_y := ground_top - 60.0
	var body := StaticBody2D.new()
	body.collision_layer = 1
	body.collision_mask = 0
	body.position = Vector2(x + length * 0.5, beam_y)
	var shape := CollisionShape2D.new()
	var rect := RectangleShape2D.new()
	rect.size = Vector2(length, 80.0)
	shape.shape = rect
	shape.position = Vector2(0.0, 10.0)
	body.add_child(shape)
	add_child(body)

	var cursor := x
	while cursor < x + length:
		var sp := _make_sprite(tex, s, Vector2(cursor + visual_step * 0.5, beam_y))
		add_child(sp)
		cursor += visual_step
	lasers.append({
		"id": id,
		"body": body,
		"block_rect": Rect2(x - 60.0, ground_top - 140.0, 80.0, 140.0),
		"blocked": false
	})


func _add_enemy(x: float, id: String) -> void:
	var tex: Texture2D = load(ENEMY_TEX_PATH)
	var s := _fit_scale(tex, Vector2(128.0, 128.0))
	var pos := Vector2(x, ground_top - 70.0)
	var sp := _make_sprite(tex, s, pos)
	add_child(sp)
	enemies.append({"id": id, "sprite": sp, "pos": pos, "radius": 110.0, "distracted": false})


func _add_exit(exit_pos: Vector2) -> void:
	var tex: Texture2D = load(EXIT_TEX_PATH)
	var s := _fit_scale(tex, Vector2(128.0, 192.0))
	exit_sprite = _make_sprite(tex, s, exit_pos)
	add_child(exit_sprite)
	exit_rect = Rect2(exit_pos.x - 70.0, exit_pos.y - 100.0, 140.0, 200.0)


func _physics_process(delta: float) -> void:
	if paused or completed:
		return
	if Input.is_action_just_pressed("pause"):
		pause_requested.emit()
		return
	if Input.is_action_just_pressed("reset"):
		reset_level()
		return
	if loop_time <= 0.0:
		_rewind()
		return

	player.update_movement(delta)
	_handle_live_interact()
	_update_ghosts(sim_tick)
	_recompute_props()
	_record_current(sim_tick)
	if _check_exit():
		return
	loop_time = maxf(loop_time - delta, 0.0)
	emit_hud_now()
	sim_tick += 1
	if loop_time <= 0.0:
		_rewind()


func emit_hud_now() -> void:
	hud_update.emit(loop_time, loop_count, _held_required_count(), required_prop_ids.size(), _get_ghost_fractions())


func _handle_live_interact() -> void:
	if not Input.is_action_just_pressed("interact"):
		return
	for s in switch_nodes:
		var pos: Vector2 = s["pos"] as Vector2
		if player.global_position.distance_to(pos) <= 70.0:
			var active: bool = bool(s["active"])
			s["active"] = not active
			current_track.record_interact(sim_tick, String(s["id"]))
			return


func _update_ghosts(tick: int) -> void:
	for i: int in range(tracks.size()):
		if i >= ghost_sprites.size():
			break
		var g: Sprite2D = ghost_sprites[i]
		var track = tracks[i]
		if tick < track.positions.size():
			g.visible = true
			g.position = track.positions[tick]
			g.flip_h = track.flips[tick]
		else:
			g.visible = false
		for ev_v in track.interact_events:
			var ev: Dictionary = ev_v
			if int(ev.get("tick", -1)) == tick:
				_toggle_switch_id(String(ev.get("switch_id", "")))


func _toggle_switch_id(id: String) -> void:
	for s in switch_nodes:
		if String(s["id"]) == id:
			var active: bool = bool(s["active"])
			s["active"] = not active
			return


func _recompute_props() -> void:
	var actors := _actor_positions()
	for p in pressure_plates:
		var active := _any_in_rect(actors, p["rect"] as Rect2)
		p["active"] = active
		var sp: Sprite2D = p["sprite"] as Sprite2D
		sp.modulate = Color(0.4, 0.9, 1.0) if active else Color(1.0, 1.0, 1.0)
		sp.position.y = float(p["base_y"]) - 4.0 if active else float(p["base_y"])
	for b in button_nodes:
		var active := _any_in_rect(actors, b["rect"] as Rect2)
		b["active"] = active
		var sp: Sprite2D = b["sprite"] as Sprite2D
		sp.modulate = Color(1.0, 0.7, 0.2) if active else Color(1.0, 1.0, 1.0)
	for d in door_nodes:
		var open := _any_in_rect(actors, d["hold_rect"] as Rect2)
		d["open"] = open
		var body: StaticBody2D = d["body"] as StaticBody2D
		body.collision_layer = 0 if open else 1
		var sp: Sprite2D = d["sprite"] as Sprite2D
		sp.modulate = Color(0.35, 1.0, 0.35) if open else Color(1.0, 1.0, 1.0)
	for l in lasers:
		var blocked := _any_in_rect(actors, l["block_rect"] as Rect2)
		l["blocked"] = blocked
		var body: StaticBody2D = l["body"] as StaticBody2D
		body.collision_layer = 0 if blocked else 1
	for e in enemies:
		var distracted := _any_in_radius(actors, e["pos"] as Vector2, float(e["radius"]))
		e["distracted"] = distracted
		var sp: Sprite2D = e["sprite"] as Sprite2D
		sp.self_modulate = Color(0.4, 0.7, 1.0) if distracted else Color(1.0, 1.0, 1.0)
	for s in switch_nodes:
		var sp: Sprite2D = s["sprite"] as Sprite2D
		sp.rotation = -0.4 if bool(s["active"]) else 0.0


func _actor_positions() -> Array[Vector2]:
	var arr: Array[Vector2] = []
	if player != null:
		arr.append(player.global_position)
	for g in ghost_sprites:
		if is_instance_valid(g) and g.visible:
			arr.append(g.global_position)
	return arr


func _any_in_rect(positions: Array[Vector2], rect: Rect2) -> bool:
	for pos_v in positions:
		var pos: Vector2 = pos_v as Vector2
		if rect.has_point(pos):
			return true
	return false


func _any_in_radius(positions: Array[Vector2], center: Vector2, radius: float) -> bool:
	for pos_v in positions:
		var pos: Vector2 = pos_v as Vector2
		if pos.distance_to(center) <= radius:
			return true
	return false


func _record_current(tick: int) -> void:
	if player != null:
		current_track.record(tick, player.global_position, player.facing_left)


func _held_required_count() -> int:
	var count := 0
	for p in pressure_plates:
		if bool(p["active"]):
			count += 1
	for b in button_nodes:
		if bool(b["active"]):
			count += 1
	return count


func _get_ghost_fractions() -> Array[float]:
	var arr: Array[float] = []
	var frac: float = clampf(float(sim_tick) / float(MAX_TICKS), 0.0, 1.0)
	for i: int in range(tracks.size()):
		arr.append(frac)
	return arr


func _check_exit() -> bool:
	if _held_required_count() < required_prop_ids.size():
		return false
	if player == null:
		return false
	if exit_rect.has_point(player.global_position):
		completed = true
		level_completed.emit(loop_count, maxf(LOOP_DURATION - loop_time, 0.0))
		return true
	return false


func _rewind() -> void:
	if current_track != null:
		current_track.finalize(sim_tick)
		if current_track.tick_count > 0:
			tracks.append(current_track)
	if tracks.size() > max_loops:
		tracks.pop_front()
	current_track = LoopTrack.new()
	_sync_ghost_nodes()
	_reset_world_props()
	player.global_position = spawn
	player.velocity = Vector2.ZERO
	loop_time = LOOP_DURATION
	sim_tick = 0
	loop_count += 1
	flash_timer = 0.35
	emit_hud_now()


func reset_level() -> void:
	tracks.clear()
	current_track = LoopTrack.new()
	_sync_ghost_nodes()
	_reset_world_props()
	player.global_position = spawn
	player.velocity = Vector2.ZERO
	loop_time = LOOP_DURATION
	sim_tick = 0
	loop_count = 1
	completed = false
	flash_timer = 0.0
	emit_hud_now()


func _reset_world_props() -> void:
	for p in pressure_plates:
		p["active"] = false
		var sp: Sprite2D = p["sprite"] as Sprite2D
		sp.position.y = float(p["base_y"])
	for b in button_nodes:
		b["active"] = false
	for s in switch_nodes:
		s["active"] = false
		var sp: Sprite2D = s["sprite"] as Sprite2D
		sp.rotation = 0.0
	for d in door_nodes:
		d["open"] = false
		var body: StaticBody2D = d["body"] as StaticBody2D
		body.collision_layer = 1
	for l in lasers:
		l["blocked"] = false
		var body: StaticBody2D = l["body"] as StaticBody2D
		body.collision_layer = 1
	for e in enemies:
		e["distracted"] = false


func _sync_ghost_nodes() -> void:
	for g in ghost_sprites:
		if is_instance_valid(g):
			remove_child(g)
			g.queue_free()
	ghost_sprites.clear()
	var tex: Texture2D = load(PLAYER_TEX_PATH)
	for i: int in range(tracks.size()):
		var g := Sprite2D.new()
		g.texture = tex
		g.centered = true
		g.scale = Vector2(0.25, 0.25)
		g.texture_filter = CanvasItem.TEXTURE_FILTER_LINEAR
		var col: Color = GHOST_COLORS[i % GHOST_COLORS.size()]
		col.a = 0.5
		g.modulate = col
		g.z_index = 5
		add_child(g)
		ghost_sprites.append(g)


func _add_static_track(pos: Vector2) -> void:
	var track = LoopTrack.new()
	for i: int in range(MAX_TICKS):
		track.positions.append(pos)
		track.flips.append(false)
	track.tick_count = MAX_TICKS
	tracks.append(track)


func _add_dynamic_track() -> void:
	var track = LoopTrack.new()
	for i: int in range(MAX_TICKS):
		var wave: float = sin(float(i) * 0.02)
		var pos := spawn + Vector2(110.0 + 220.0 * wave, 0.0)
		if i > 640 and i < 690:
			pos.y -= 70.0
		track.positions.append(pos)
		track.flips.append(wave < 0.0)
	track.tick_count = MAX_TICKS
	tracks.append(track)


func _prefill_current_track_for_scenario() -> void:
	if current_track == null:
		current_track = LoopTrack.new()
	for i: int in range(810):
		var wave: float = sin(float(i) * 0.018)
		current_track.record(i, spawn + Vector2(120.0 + 220.0 * wave, 0.0), wave < 0.0)


func _scenario_position(key: String) -> Vector2:
	if key == "door" and door_nodes.size() > 0:
		var d: Dictionary = door_nodes[0]
		return (d["hold_rect"] as Rect2).get_center()
	if key.length() > 5 and key.substr(0, 5) == "plate":
		var idx := maxi(key.substr(5).to_int() - 1, 0)
		if idx < pressure_plates.size():
			return pressure_plates[idx]["pos"] as Vector2
	return spawn


func apply_scenario(id: String) -> void:
	scenario_id = id
	if id == "loop_rewrite_imminent":
		_add_dynamic_track()
		_prefill_current_track_for_scenario()
		loop_time = 3.0
		sim_tick = 810
		loop_count = 2
	elif id == "multi_ghost_door":
		_add_static_track(_scenario_position("door"))
		_add_static_track(_scenario_position("plate2"))
		loop_time = 30.0
		sim_tick = 0
		loop_count = 3
	elif id == "laser_block_bridge":
		for i: int in range(3):
			_add_static_track(_scenario_position("plate%d" % (i + 1)))
		loop_time = 25.0
		sim_tick = 0
		loop_count = 4
	elif id == "four_loop_finale":
		for i: int in range(4):
			_add_static_track(_scenario_position("plate%d" % (i + 1)))
		player.global_position = exit_rect.get_center() + Vector2(-12.0, 0.0)
		loop_time = 20.0
		sim_tick = 0
		loop_count = 4
	elif id == "result_state":
		for i: int in range(4):
			_add_static_track(_scenario_position("plate%d" % (i + 1)))
		player.global_position = exit_rect.get_center()
		loop_time = 20.0
		sim_tick = 0
		loop_count = 2
	_sync_ghost_nodes()
	_reset_world_props()
	emit_hud_now()

scripts/main.gd:
extends Node2D

const LevelScript = preload("res://scripts/level.gd")
const LevelDataScript = preload("res://scripts/level_data.gd")
const TimelineBarScript = preload("res://scripts/timeline_bar.gd")
var _title_texture_cache: Texture2D = null
var _button_texture_cache: Texture2D = null
var _panel_texture_cache: Texture2D = null

var ui_layer: CanvasLayer
var hud_root: Control
var hud_timer_label: Label
var hud_loop_label: Label
var hud_status_label: Label
var hud_flash_rect: ColorRect
var timeline_bar: Control
var pause_root: Control = null
var current_level = null
var current_level_id: String = "1-1"
var pending_scenario: String = ""


func _get_title_texture() -> Texture2D:
	if _title_texture_cache == null:
		_title_texture_cache = load("res://assets/normalized/title_background/title_background.png")
	return _title_texture_cache


func _get_button_texture() -> Texture2D:
	if _button_texture_cache == null:
		_button_texture_cache = load("res://assets/normalized/ui_button/button_normal.png")
	return _button_texture_cache


func _get_panel_texture() -> Texture2D:
	if _panel_texture_cache == null:
		_panel_texture_cache = load("res://assets/normalized/ui_panel/panel.png")
	return _panel_texture_cache


func _ready() -> void:
	_ensure_input_actions()
	ui_layer = CanvasLayer.new()
	ui_layer.layer = 10
	add_child(ui_layer)
	_parse_args()
	if pending_scenario != "":
		_start_scenario(pending_scenario)
	else:
		_show_title()


func _process(_delta: float) -> void:
	if is_instance_valid(current_level) and hud_flash_rect != null:
		var ft_v = current_level.get("flash_timer")
		var ft: float = 0.0
		if ft_v != null:
			ft = float(ft_v)
		if ft > 0.0:
			hud_flash_rect.visible = true
			hud_flash_rect.color = Color(1.0, 1.0, 1.0, clampf(ft * 2.5, 0.0, 0.7))
		else:
			hud_flash_rect.visible = false


func _ensure_input_actions() -> void:
	_define_action("move_left", [KEY_A, KEY_LEFT])
	_define_action("move_right", [KEY_D, KEY_RIGHT])
	_define_action("jump", [KEY_SPACE, KEY_W])
	_define_action("interact", [KEY_ENTER])
	_define_action("reset", [KEY_R])
	_define_action("pause", [KEY_ESCAPE])


func _define_action(action: String, keys: Array) -> void:
	if not InputMap.has_action(action):
		InputMap.add_action(action)
	for key_v in keys:
		var key: int = int(key_v)
		var ev := InputEventKey.new()
		ev.keycode = key
		ev.physical_keycode = key
		InputMap.action_add_event(action, ev)


func _parse_args() -> void:
	var args := OS.get_cmdline_user_args()
	for i: int in range(args.size()):
		if args[i] == "--scenario" and i + 1 < args.size():
			pending_scenario = str(args[i + 1])
			return


func _clear_ui() -> void:
	if ui_layer == null:
		return
	for child in ui_layer.get_children():
		ui_layer.remove_child(child)
		child.queue_free()
	hud_root = null
	hud_timer_label = null
	hud_loop_label = null
	hud_status_label = null
	hud_flash_rect = null
	timeline_bar = null
	pause_root = null


func _clear_world() -> void:
	if is_instance_valid(current_level):
		remove_child(current_level)
		current_level.queue_free()
	current_level = null


func _make_full_rect() -> Control:
	var c := Control.new()
	c.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	c.mouse_filter = Control.MOUSE_FILTER_IGNORE
	return c


func _add_background(parent: Control, tex: Texture2D) -> void:
	var tr := TextureRect.new()
	tr.texture = tex
	tr.expand_mode = TextureRect.EXPAND_IGNORE_SIZE
	tr.stretch_mode = TextureRect.STRETCH_KEEP_ASPECT_COVERED
	tr.mouse_filter = Control.MOUSE_FILTER_IGNORE
	tr.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	tr.texture_filter = CanvasItem.TEXTURE_FILTER_LINEAR
	parent.add_child(tr)


func _make_panel(panel_pos: Vector2, panel_size: Vector2) -> TextureRect:
	var tr := TextureRect.new()
	tr.texture = _get_panel_texture()
	tr.expand_mode = TextureRect.EXPAND_IGNORE_SIZE
	tr.stretch_mode = TextureRect.STRETCH_SCALE
	tr.position = panel_pos
	tr.size = panel_size
	tr.mouse_filter = Control.MOUSE_FILTER_IGNORE
	tr.texture_filter = CanvasItem.TEXTURE_FILTER_LINEAR
	return tr


func _make_label(text: String, font_size: int, pos: Vector2, size: Vector2) -> Label:
	var label := Label.new()
	label.text = text
	label.add_theme_font_size_override("font_size", font_size)
	label.add_theme_color_override("font_color", Color(0.95, 0.96, 1.0))
	label.position = pos
	label.size = size
	label.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
	label.vertical_alignment = VERTICAL_ALIGNMENT_CENTER
	label.mouse_filter = Control.MOUSE_FILTER_IGNORE
	return label


func _make_texture_button(text: String, text_size: int, btn_size: Vector2, callback: Callable) -> TextureButton:
	var tb := TextureButton.new()
	tb.texture_normal = _get_button_texture()
	tb.ignore_texture_size = true
	tb.stretch_mode = TextureButton.STRETCH_SCALE
	tb.custom_minimum_size = btn_size
	tb.size = btn_size
	tb.mouse_default_cursor_shape = Control.CURSOR_POINTING_HAND
	tb.texture_filter = CanvasItem.TEXTURE_FILTER_LINEAR
	tb.pressed.connect(callback)

	var label := Label.new()
	label.text = text
	label.add_theme_font_size_override("font_size", text_size)
	label.add_theme_color_override("font_color", Color(1.0, 1.0, 1.0))
	label.mouse_filter = Control.MOUSE_FILTER_IGNORE
	label.set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	label.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
	label.vertical_alignment = VERTICAL_ALIGNMENT_CENTER
	tb.add_child(label)
	return tb


