func _on_hud_update(loop_time: float, loop_count: int, held: int, required: int, fractions: Array[float]) -> void:
	if hud_timer_label == null:
		return
	hud_timer_label.text = "Time: %05.2f" % maxf(loop_time, 0.0)
	hud_loop_label.text = "Loop %d" % loop_count
	hud_status_label.text = "Switches Held: %d / %d" % [held, required]
	if timeline_bar != null:
		timeline_bar.set_state(fractions, loop_time)


