	_show_level_select(chapter)


func _on_level_selected(level_id: String) -> void:
	_start_level(level_id, "")


func _start_scenario(id: String) -> void:
	var level_id := "1-1"
	match id:
		"loop_rewrite_imminent":
			level_id = "1-1"
		"multi_ghost_door":
			level_id = "2-1"
		"laser_block_bridge":
			level_id = "3-1"
		"four_loop_finale", "result_state":
			level_id = "4-1"
		_:
			level_id = "1-1"
	_start_level(level_id, id)


func _start_level(level_id: String, scenario: String) -> void:
	_clear_ui()
	_clear_world()
	_show_hud()
	current_level_id = level_id
	var level = LevelScript.new()
	level.level_id = level_id
	level.scenario_id = scenario
	level.hud_update.connect(_on_hud_update)
	level.level_completed.connect(_on_level_completed)
	level.pause_requested.connect(_on_pause_requested)
	add_child(level)
	current_level = level
	if scenario != "":
		level.apply_scenario(scenario)
	level.emit_hud_now()


