func _on_pause_requested() -> void:
	if is_instance_valid(current_level) and not current_level.paused:
		_show_pause_overlay()


func _show_pause_overlay() -> void:
	_close_pause()
	if is_instance_valid(current_level):
		current_level.paused = true
	var root := _make_full_rect()
	root.mouse_filter = Control.MOUSE_FILTER_STOP
	ui_layer.add_child(root)
	pause_root = root
	var panel := _make_panel(Vector2(410, 170), Vector2(460, 360))
	root.add_child(panel)
	root.add_child(_make_label("Paused", 42, Vector2(500, 200), Vector2(280, 60)))
	var resume := _make_texture_button("Resume", 24, Vector2(260, 64), func(): _resume_pause())
	resume.position = Vector2(510, 300)
	root.add_child(resume)
	var restart := _make_texture_button("Restart Loop", 24, Vector2(260, 64), func(): _restart_level())
	restart.position = Vector2(510, 380)
	root.add_child(restart)
	var menu := _make_texture_button("Chapter Menu", 24, Vector2(260, 64), func(): _return_to_chapter_from_pause())
	menu.position = Vector2(510, 460)
	root.add_child(menu)


func _close_pause() -> void:
	if is_instance_valid(pause_root):
		ui_layer.remove_child(pause_root)
		pause_root.queue_free()
	pause_root = null
	if is_instance_valid(current_level):
		current_level.paused = false


func _resume_pause() -> void:
	_close_pause()


func _restart_level() -> void:
	_close_pause()
	if is_instance_valid(current_level):
		current_level.reset_level()


func _return_to_chapter_from_pause() -> void:
	_close_pause()
	_show_chapter_menu()
